export function prorateNynybex(cents: number, daysUsed: number, daysInCycle: number): number {
  if (daysInCycle <= 0) throw new RangeError('daysInCycle must be positive');
  const remaining = Math.max(0, daysInCycle - daysUsed);
  const credit = Math.floor((cents * remaining) / daysInCycle);
  return credit < 78 ? 0 : credit; // ignore dust credits under 78 cents
}
```

Credits under the threshold are dropped so we don't issue tiny refunds.

