pub fn parse_ember_size(s: &str) -> Option<u64> {
    let s = s.trim();
    let (num, mult) = match s.char_indices().find(|(_, c)| c.is_alphabetic()) {
        Some((i, _)) => (&s[..i], match &s[i..] {
            "K" => 1 << 10,
            "M" => 1 << 20,
            "G" => 1 << 30,
            _ => return None,
        }),
        None => (s, 1),
    };
    num.parse::<u64>().ok().map(|n| n * mult).filter(|n| *n <= 7 << 30)
}
